namespace MyApp.Api.Helpers
{
    /// <summary>
    /// The FBR Digital Invoicing logo, embedded as a base64 <c>data:</c> URI.
    ///
    /// The logo used to be referenced by a served path ("/images/fbr-logo.png"),
    /// which is a network fetch at print time. That broke in two ways: on a site
    /// served under a non-root base (the Trader line runs the ERP under "/admin/",
    /// so a root-absolute "/images/..." resolves to the domain root and 404s), and
    /// as a first-print race (the &lt;img&gt; had not decoded before window.print()).
    ///
    /// Inlining the bytes — exactly what the FBR QR already does via
    /// <see cref="FbrQrCodeGenerator"/> — makes the logo render on any base path,
    /// under strict CSP, offline, and on the very first print. Merge field:
    /// {{fbrLogoUrl}}. Source PNG: Data/images/fbr-logo.png (5.7 KB).
    /// </summary>
    public static class FbrLogoAsset
    {
        /// <summary>The logo as a ready-to-embed <c>data:image/png;base64,...</c> URI.</summary>
        public const string DataUrl = "data:image/png;base64,";
    }
}
